// tools/build-street-furniture-models.mjs: writes assets/props/poster-column.glb and assets/props/publication-corral.glb.
// A script that runs once on a developer machine (node tools/build-street-furniture-models.mjs) and writes the two
// low-poly models the game loads, drawn here from boxes and lathes: nothing is downloaded, generated by a paid
// service or taken from a photograph. Proportions are approximations of the City's coordinated street furniture
// (Open Data gives the type and the point, not a drawing); the poster art is original abstract art with no lettering,
// no brand and no copyrighted work. Metres, +Y up, base on the ground, +Z the front.
import fs from 'node:fs';
import zlib from 'node:zlib';
import { Document, NodeIO } from '@gltf-transform/core';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));

// ------------------------------------------------------------------------------------------------ PNG (one-off encoder)
function crc32(buf) {
  let c, crc = 0xffffffff;
  for (let n = 0; n < buf.length; n++) {
    c = (crc ^ buf[n]) & 0xff;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    crc = (crc >>> 8) ^ c;
  }
  return (crc ^ 0xffffffff) >>> 0;
}
function png(w, h, rgba) {
  const chunk = (type, data) => {
    const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
    const td = Buffer.concat([Buffer.from(type), data]);
    const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td));
    return Buffer.concat([len, td, crc]);
  };
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 6;
  const raw = Buffer.alloc((w * 4 + 1) * h);
  for (let y = 0; y < h; y++) { raw[y * (w * 4 + 1)] = 0; rgba.copy(raw, y * (w * 4 + 1) + 1, y * w * 4, (y + 1) * w * 4); }
  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(raw, { level: 9 })), chunk('IEND', Buffer.alloc(0))]);
}

// ------------------------------------------------------------------------------------------------ original abstract posters
// Four posters, side by side in one atlas, each PW x PH px. u, v in 0..1 (v down). Colours 0..255.
const PW = 128, PH = 320;
const mix = (a, b, t) => a.map((x, i) => x + (b[i] - x) * Math.max(0, Math.min(1, t)));
const step = (a, b, x) => Math.max(0, Math.min(1, (x - a) / (b - a)));
const posters = [
  // dawn: stacked sun discs over a gradient sky, a dark band at the foot
  (u, v) => {
    let c = mix([250, 188, 92], [214, 70, 108], v * 1.1);
    const d = Math.hypot(u - 0.5, (v - 0.56) * 2.4);
    for (let i = 0; i < 4; i++) if (d < 0.46 - i * 0.1) c = i % 2 ? [248, 226, 168] : [236, 120, 74];
    if (v > 0.82) c = [48, 44, 74];
    return c;
  },
  // blocks: Bauhaus-like rectangles and a diagonal
  (u, v) => {
    let c = [238, 230, 208];
    if (u < 0.55 && v < 0.4) c = [30, 120, 128];
    if (u > 0.4 && v > 0.3 && v < 0.62) c = [234, 190, 52];
    if (Math.abs((u - 0.5) * 1.6 - (v - 0.5)) < 0.05) c = [28, 30, 40];
    if (v > 0.68 && u < 0.7) c = [196, 62, 52];
    if (Math.hypot(u - 0.72, (v - 0.82) * 2.2) < 0.2) c = [30, 120, 128];
    return c;
  },
  // waves: layered sine bands, deep blue to green
  (u, v) => {
    const band = Math.floor((v + 0.06 * Math.sin(u * 9 + v * 6)) * 9);
    const t = Math.max(0, Math.min(8, band)) / 8;
    let c = mix([18, 52, 120], [96, 200, 150], t);
    if (band % 2) c = c.map((x) => x * 0.86);
    if (v < 0.1) c = [244, 240, 226];
    return c;
  },
  // halftone: a red field of dots growing downwards under one large disc
  (u, v) => {
    let c = [206, 54, 60];
    const gx = (u * 8) % 1, gy = (v * 20) % 1, r = 0.12 + 0.3 * v;
    if (Math.hypot(gx - 0.5, gy - 0.5) < r && v > 0.45) c = [244, 214, 196];
    if (Math.hypot(u - 0.5, (v - 0.22) * 2.4) < 0.3) c = [26, 32, 52];
    return c;
  }
];
function posterAtlas() {
  const W = PW * posters.length, rgba = Buffer.alloc(W * PH * 4);
  for (let p = 0; p < posters.length; p++) for (let y = 0; y < PH; y++) for (let x = 0; x < PW; x++) {
    let c = posters[p](x / PW, y / PH);
    const edge = Math.min(x, PW - 1 - x, y, PH - 1 - y); // a paper margin round each poster
    if (edge < 5) c = [240, 236, 226];
    else if (edge < 7) c = c.map((v) => v * 0.8);
    const o = ((y * W) + p * PW + x) * 4;
    rgba[o] = c[0]; rgba[o + 1] = c[1]; rgba[o + 2] = c[2]; rgba[o + 3] = 255;
  }
  return { png: png(W, PH, rgba), w: W, h: PH };
}

// ------------------------------------------------------------------------------------------------ mesh builder
class Mesh {
  constructor() { this.pos = []; this.nrm = []; this.uv = []; this.col = []; this.idx = []; }
  quad(a, b, c, d, color = [1, 1, 1], uvs = null) { // counter-clockwise seen from the front
    const n = norm(cross(sub(b, a), sub(d, a)));
    const base = this.pos.length / 3;
    for (const p of [a, b, c, d]) { this.pos.push(...p); this.nrm.push(...n); this.col.push(...color, 1); }
    this.uv.push(...(uvs || [0, 0, 0, 0, 0, 0, 0, 0]));
    this.idx.push(base, base + 1, base + 2, base, base + 2, base + 3);
  }
  box(x0, y0, z0, x1, y1, z1, color) {
    const q = (a, b, c, d) => this.quad(a, b, c, d, color);
    q([x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]); // +z
    q([x1, y0, z0], [x0, y0, z0], [x0, y1, z0], [x1, y1, z0]); // -z
    q([x1, y0, z1], [x1, y0, z0], [x1, y1, z0], [x1, y1, z1]); // +x
    q([x0, y0, z0], [x0, y0, z1], [x0, y1, z1], [x0, y1, z0]); // -x
    q([x0, y1, z1], [x1, y1, z1], [x1, y1, z0], [x0, y1, z0]); // top
    q([x0, y0, z0], [x1, y0, z0], [x1, y0, z1], [x0, y0, z1]); // bottom
  }
  // a ring of n flat facets between two radii and heights (a frustum), optionally a cap
  frustum(r0, y0, r1, y1, n, color, { capTop = false, uv = null } = {}) {
    for (let i = 0; i < n; i++) {
      const a0 = (i / n) * Math.PI * 2, a1 = ((i + 1) / n) * Math.PI * 2;
      const p = (r, y, a) => [Math.sin(a) * r, y, Math.cos(a) * r];
      this.quad(p(r0, y0, a0), p(r0, y0, a1), p(r1, y1, a1), p(r1, y1, a0), color, uv ? uv(i) : null);
    }
    if (capTop) {
      const c = [0, y1, 0], base = this.pos.length / 3;
      for (let i = 0; i < n; i++) {
        const a0 = (i / n) * Math.PI * 2, a1 = ((i + 1) / n) * Math.PI * 2;
        const v = [[Math.sin(a0) * r1, y1, Math.cos(a0) * r1], [Math.sin(a1) * r1, y1, Math.cos(a1) * r1], c];
        for (const q of [v[2], v[1], v[0]]) { this.pos.push(...q); this.nrm.push(0, 1, 0); this.col.push(...color, 1); this.uv.push(0, 0); }
        const b = base + i * 3; this.idx.push(b, b + 1, b + 2);
      }
    }
  }
}
const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const norm = (a) => { const l = Math.hypot(...a) || 1; return a.map((x) => x / l); };
const hex = (h) => [(h >> 16 & 255) / 255, (h >> 8 & 255) / 255, (h & 255) / 255].map((c) => Math.pow(c, 2.2)); // linear

function addMesh(doc, scene, name, m, material) {
  const buf = doc.getRoot().listBuffers()[0];
  const acc = (type, array, Ctor) => doc.createAccessor().setType(type).setArray(new Ctor(array)).setBuffer(buf);
  const prim = doc.createPrimitive()
    .setAttribute('POSITION', acc('VEC3', m.pos, Float32Array))
    .setAttribute('NORMAL', acc('VEC3', m.nrm, Float32Array))
    .setAttribute('TEXCOORD_0', acc('VEC2', m.uv, Float32Array))
    .setAttribute('COLOR_0', acc('VEC4', m.col, Float32Array))
    .setIndices(acc('SCALAR', m.idx, Uint16Array))
    .setMaterial(material);
  const mesh = doc.createMesh(name).addPrimitive(prim);
  scene.addChild(doc.createNode(name).setMesh(mesh));
}

// ------------------------------------------------------------------------------------------------ poster column
const SIDES = 16; // four facets to a poster
function posterColumn() {
  const doc = new Document(); doc.createBuffer();
  const scene = doc.createScene('poster-column');
  const atlas = posterAtlas();
  const tex = doc.createTexture('posters').setImage(atlas.png).setMimeType('image/png');
  const posterMat = doc.createMaterial('poster-surface').setBaseColorTexture(tex).setRoughnessFactor(0.55).setMetallicFactor(0);
  const bodyMat = doc.createMaterial('column-metal').setRoughnessFactor(0.5).setMetallicFactor(0.6);
  // the drum the posters are pasted on: 1.8 m of paper
  const drum = new Mesh();
  drum.frustum(0.45, 0.34, 0.45, 2.14, SIDES, [1, 1, 1], { uv: (i) => {
    const poster = Math.floor(i / 4) % posters.length, f = i % 4;
    const u0 = (poster * PW + (f / 4) * PW) / atlas.w, u1 = (poster * PW + ((f + 1) / 4) * PW) / atlas.w;
    return [u0, 1, u1, 1, u1, 0, u0, 0]; // a, b = bottom, c, d = top
  } });
  addMesh(doc, scene, 'posters', drum, posterMat);
  const dark = hex(0x2c3034), band = hex(0x41484d), cap = hex(0x23272a);
  const body = new Mesh();
  body.frustum(0.52, 0, 0.5, 0.2, 12, dark, { capTop: false }); // plinth
  body.frustum(0.5, 0.2, 0.46, 0.34, 12, band);
  body.frustum(0.5, 2.14, 0.52, 2.22, 16, band); // the ring over the paper
  body.frustum(0.52, 2.22, 0.52, 2.3, 16, cap);
  body.frustum(0.52, 2.3, 0.3, 2.46, 16, cap); // the dome
  body.frustum(0.3, 2.46, 0.1, 2.54, 16, cap, { capTop: true });
  addMesh(doc, scene, 'frame', body, bodyMat);
  return doc;
}

// ------------------------------------------------------------------------------------------------ publication corral
function publicationCorral() {
  const doc = new Document(); doc.createBuffer();
  const scene = doc.createScene('publication-corral');
  const mat = doc.createMaterial('corral').setRoughnessFactor(0.55).setMetallicFactor(0.35);
  const m = new Mesh();
  const frame = hex(0x2b2f33), rail = hex(0x3a4045);
  const W = 1.5, D = 0.62, H = 1.12, x0 = -W / 2, x1 = W / 2, z0 = -D / 2, z1 = D / 2, t = 0.05, r = 0.035;
  for (const [x, z] of [[x0, z0], [x1 - t, z0], [x0, z1 - t], [x1 - t, z1 - t]]) m.box(x, 0, z, x + t, H, z + t, frame); // posts
  for (const y of [0.08, 0.58, H - 0.04]) { // rails round the pen: low, middle, top
    const a = y > 1 ? 0.045 : r;
    m.box(x0, y, z0, x1, y + a, z0 + r, rail);
    m.box(x0, y, z1 - r, x1, y + a, z1, rail);
    m.box(x0, y, z0, x0 + r, y + a, z1, rail);
    m.box(x1 - r, y, z0, x1, y + a, z1, rail);
  }
  m.box(x0, 0, z0, x1, 0.06, z1, frame); // the base plate
  // three publication boxes inside: a dark pedestal body, a coloured lid and a pale front window
  const colours = [hex(0xb8322a), hex(0x2a5fa8), hex(0xe0a722)];
  colours.forEach((c, i) => {
    const bw = 0.4, cx = x0 + 0.1 + bw / 2 + i * (bw + 0.08), bx0 = cx - bw / 2, bx1 = cx + bw / 2;
    m.box(bx0, 0.06, -0.2, bx1, 0.86, 0.2, hex(0x4a5258));
    m.box(bx0 - 0.01, 0.86, -0.21, bx1 + 0.01, 0.96, 0.21, c);
    m.box(bx0 + 0.04, 0.4, 0.2, bx1 - 0.04, 0.78, 0.215, hex(0xd9dde0)); // the paper window
    m.box(bx0 + 0.06, 0.12, 0.2, bx1 - 0.06, 0.3, 0.212, c); // the coin door
  });
  addMesh(doc, scene, 'corral', m, mat);
  return doc;
}

const io = new NodeIO();
for (const [name, doc] of [['poster-column', posterColumn()], ['publication-corral', publicationCorral()]]) {
  const out = `${root}assets/props/${name}.glb`;
  fs.writeFileSync(out, Buffer.from(await io.writeBinary(doc)));
  console.log(`[streetFurnitureModels] ${out} ${fs.statSync(out).size} bytes`);
}
